import React, { useState } from 'react';
import { Box, TextField, Button, Typography, Container, Paper, Alert, CircularProgress, Avatar } from '@mui/material';
import { PersonAdd as PersonAddIcon, Login as LoginIcon } from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import { login } from '../features/authSlice';

const Register = () => {
  const [userData, setUserData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: '',
    confirmPassword: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const validateEmail = (email) => {
    return email.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);
  };

  const validateForm = () => {
    if (!userData.firstName || !userData.lastName || !userData.email || !userData.password) {
      setError('Please fill in all fields');
      return false;
    }
    if (!validateEmail(userData.email)) {
      setError('Please enter a valid email address');
      return false;
    }
    if (userData.password !== userData.confirmPassword) {
      setError('Passwords do not match');
      return false;
    }
    if (userData.password.length < 6) {
      setError('Password must be at least 6 characters');
      return false;
    }
    return true;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!validateForm()) {
      setLoading(false);
      return;
    }

    try {
      // Mock successful registration
      await new Promise(resolve => setTimeout(resolve, 1000)); // Simulate API call
      const newUser = {
        ...userData,
        id: Date.now(),
        role: 'user'
      };
      
      dispatch(login(newUser));
      navigate('/');
    } catch (err) {
      setError('Registration failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container 
      component="main" 
      maxWidth="xs" 
      sx={{ 
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        py: 4
      }}
    >
      <Paper 
        elevation={6} 
        sx={{ 
          p: 4, 
          width: '100%',
          display: 'flex', 
          flexDirection: 'column', 
          alignItems: 'center',
          borderRadius: 2
        }}
      >
        <Avatar 
          sx={{ 
            m: 1, 
            bgcolor: 'primary.main', 
            width: 56, 
            height: 56,
            boxShadow: 2
          }}
        >
          <PersonAddIcon sx={{ fontSize: 32 }} />
        </Avatar>
        <Typography 
          component="h1" 
          variant="h5" 
          sx={{ 
            mb: 3,
            fontWeight: 'bold'
          }}
        >
          Create Account
        </Typography>
        {error && (
          <Alert 
            severity="error" 
            sx={{ 
              mt: 2, 
              mb: 2, 
              width: '100%' 
            }}
          >
            {error}
          </Alert>
        )}
        <Box 
          component="form" 
          onSubmit={handleSubmit} 
          sx={{ 
            mt: 1, 
            width: '100%' 
          }}
        >
          <TextField
            margin="normal"
            required
            fullWidth
            label="First Name"
            name="firstName"
            autoFocus
            value={userData.firstName}
            onChange={(e) => setUserData({ ...userData, firstName: e.target.value })}
          />
          <TextField
            margin="normal"
            required
            fullWidth
            label="Last Name"
            name="lastName"
            onChange={(e) => setUserData({ ...userData, lastName: e.target.value })}
          />
          <TextField
            margin="normal"
            required
            fullWidth
            label="Email Address"
            name="email"
            autoComplete="email"
            onChange={(e) => setUserData({ ...userData, email: e.target.value })}
          />
          <TextField
            margin="normal"
            required
            fullWidth
            name="password"
            label="Password"
            type="password"
            onChange={(e) => setUserData({ ...userData, password: e.target.value })}
          />
          <TextField
            margin="normal"
            required
            fullWidth
            name="confirmPassword"
            label="Confirm Password"
            type="password"
            onChange={(e) => setUserData({ ...userData, confirmPassword: e.target.value })}
          />
          <Button
            type="submit"
            fullWidth
            variant="contained"
            sx={{ 
              mt: 3, 
              mb: 2, 
              height: 48,
              borderRadius: 2,
              textTransform: 'none',
              fontSize: '1.1rem'
            }}
            disabled={loading}
            startIcon={!loading && <PersonAddIcon />}
          >
            {loading ? <CircularProgress size={24} color="inherit" /> : 'Register'}
          </Button>
          <Button
            fullWidth
            variant="outlined"
            onClick={() => navigate('/login')}
            disabled={loading}
            startIcon={<LoginIcon />}
            sx={{ 
              height: 48,
              borderRadius: 2,
              textTransform: 'none'
            }}
          >
            Already have an account? Login
          </Button>
        </Box>
      </Paper>
    </Container>
  );
};

export default Register;
